interactions.sample_code:
function maxHeapify(i, heapSize) {
  let largest = i;
  const l = left(i), r = right(i);
  if (l <= heapSize && compare(l, largest)) largest = l;
  if (r <= heapSize && compare(r, largest)) largest = r;
  if (largest !== i) {
    swap(i, largest);
    mark(largest);
    maxHeapify(largest, heapSize);
  }
}

